import { Mesh, PlaneGeometry, Object3D, Vector3, Euler } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
	// ----- Scene placement -------------------------------------------------
	const placement = config.scenePlacement ?? {};
	const position = placement.position ?? [0, 0, 0];
	const rotation = placement.rotation ?? [0, 0, 0];
	const scale = placement.scale ?? [1, 1, 1];

	// ----- Geometry size from atlas region (fallback to unit plane) -----
	let width = 1;
	let height = 1;
	if (config.atlasRegion && config.atlasRegion.sourceRect) {
		const [, , w, h] = config.atlasRegion.sourceRect; // x, y, w, h
		width = w;
		height = h;
	}

	const geometry = new PlaneGeometry(width, height);

	// ----- Texture ---------------------------------------------------------
	const imageUrl = config.assets?.imageUrl ?? null;
	const texture = imageUrl ? ctx.textureLoader.load(imageUrl) : null;

	// ----- Material --------------------------------------------------------
	const material = new MeshBasicNodeMaterial({
		map: texture,
		transparent: true,
	});

	// ----- Mesh ------------------------------------------------------------
	const mesh = new Mesh(geometry, material);
	mesh.position.set(...position);
	mesh.rotation.set(...rotation);
	mesh.scale.set(...scale);

	// ----- Handlers --------------------------------------------------------
	mesh.userData.handlers = {};

	// ----- Cleanup ---------------------------------------------------------
	const timelines = [];

	mesh.userData.cleanup = () => {
		// Kill any GSAP timelines that might have been created later
		timelines.forEach((t) => t.kill());
		// Dispose Three.js resources
		geometry.dispose();
		material.dispose();
		if (texture) texture.dispose();
	};

	// ----- No cinematic primitives to apply --------------------------------
	// (config.cinematicPrimitives is empty)

	return mesh;
}
